        return

    S = [int(x) for x in data[1:N+1]]
    max_val = max(S)

    try:
        # NumPy's FFT is implemented in C and incredibly fast, solving the polynomial 
        # convolution in O(M log M) time.
        import numpy as np

        # We need a power of 2 size that's strictly larger than the max index 
        # we can possibly get, which is 2 * max_val.
        size = 1
        while size <= 2 * max_val:
            size *= 2

        poly = np.zeros(size, dtype=np.float64)

        # Vectorized assignment is much faster than looping
        S_arr = np.array(S, dtype=np.int32)
        poly[S_arr] = 1.0

        poly_f = np.fft.rfft(poly)
        poly_sq = poly_f * poly_f
        poly_res = np.fft.irfft(poly_sq, n=size)

        # Vectorized calculation for the answer
        # Number of pairs A, C such that A + C = 2B
        vals = np.round(poly_res[2 * S_arr]).astype(np.int64)

        # We subtract 1 to remove the A=B=C case, and divide by 2 to enforce A < C.
        ans = int(np.sum((vals - 1) // 2))

        print(ans)

    except ImportError:
        # Number Theoretic Transform (NTT) fallback for PyPy or environments without NumPy.
        # The bitwise fallback would TLE (O(M^2 / word_size)) for max_val = 10^6.
        # NTT guarantees O(M log M) time complexity.
        MOD = 998244353
        size = 1
        while size <= 2 * max_val:
            size *= 2

        poly = [0] * size
        for x in S:
