                bit = n >> 1
                while j & bit:
                    j ^= bit
                    bit >>= 1
                j ^= bit
                if i < j:
                    a[i], a[j] = a[j], a[i]

            length = 2
            while length <= n:
                half = length // 2
                wlen = pow(3, (MOD - 1) // length, MOD)
                if invert:
                    wlen = pow(wlen, MOD - 2, MOD)

                w = [1] * half
                for i in range(1, half):
                    w[i] = (w[i-1] * wlen) % MOD

                for i in range(0, n, length):
                    for j in range(half):
                        u = a[i + j]
                        v = (a[i + j + half] * w[j]) % MOD
                        a[i + j] = (u + v) % MOD
                        a[i + j + half] = (u - v) % MOD
                length *= 2

            if invert:
                inv_n = pow(n, MOD - 2, MOD)
                for i in range(n):
                    a[i] = (a[i] * inv_n) % MOD

        ntt(poly, False)
        for i in range(size):
            poly[i] = (poly[i] * poly[i]) % MOD
        ntt(poly, True)

        ans = 0
        for b in S:
            val = poly[2 * b]
            ans += (val - 1) // 2

        print(ans)

